// Package setdata holds the per-set booster specs the draft stack plays
// with: one embedded JSON file per set, generated by internal/gen from the
// trimmed MTGJSON booster inputs (draft/limited/setdata/mtgjson/<SET>.json, MIT)
// and committed. Each file carries every collation MTGJSON publishes for
// the set — "play", the paper Play Booster, and "play-arena", the MTG Arena
// variant — and LoadCollation picks one.
//
// The package is pure: it reads nothing but its embedded files and imports
// nothing but the standard library and limited.
package setdata

import (
	"bytes"
	"embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/adams-shaun/gorge/draft/limited"
)

//go:embed sets/*.json
var sets embed.FS

// Collation names one booster collation of a set, the key MTGJSON spells
// under the file's "configs".
type Collation string

// The collations the embedded data carries: Play is the paper Play Booster,
// Arena the MTG Arena variant of the same product.
const (
	Play  Collation = "play"
	Arena Collation = "play-arena"
)

// DefaultCollation is the collation Load (and so every caller that does not
// name one) serves: MTG Arena, because the pick ratings are 17Lands Arena
// data.
const DefaultCollation = Arena

// SheetCard is one card on a booster sheet: a printing the pack generator
// draws, carrying the MTGJSON facts. Weight is the card's collation weight;
// the sheets' draws are weighted by it.
type SheetCard struct {
	UUID   string         `json:"uuid"`
	Name   string         `json:"name"`
	Set    string         `json:"set"`
	Number string         `json:"number"`
	Rarity limited.Rarity `json:"rarity"`
	Colors string         `json:"colors"`
	Weight int            `json:"weight"`
}

// Sheet is one MTGJSON collation sheet: the cards it can put in a pack, its
// total weight (the sum of the card weights), and the collation flags that
// change how a pack draws from it.
type Sheet struct {
	TotalWeight     int         `json:"total_weight"`
	Foil            bool        `json:"foil,omitempty"`
	BalanceColors   bool        `json:"balance_colors,omitempty"`
	AllowDuplicates bool        `json:"allow_duplicates,omitempty"`
	Fixed           bool        `json:"fixed,omitempty"`
	Cards           []SheetCard `json:"cards"`
}

// Variant is one pack recipe: its share of the collation's packs (Weight,
// against the config's TotalWeight) and the sheets it draws from, each with
// the number of cards it contributes to the pack (Contents).
type Variant struct {
	Weight   int            `json:"weight"`
	Contents map[string]int `json:"contents"`
}

// Config is one collation's full configuration, exactly the MTGJSON
// semantics: the variants and weighted sheets a pack opens from.
type Config struct {
	SourceSetCodes []string         `json:"source_set_codes"`
	TotalWeight    int              `json:"total_weight"`
	Variants       []Variant        `json:"variants"`
	Sheets         map[string]Sheet `json:"sheets"`
}

// Spec is one set's booster spec for one collation: the set's facts plus
// the collation's config. PackSize is the pack size every variant of the
// config produces (Validate checks it is constant across the variants).
type Spec struct {
	Code string `json:"code"`
	Name string `json:"name"`
	// Collation is the collation this Spec was loaded for. It is runtime
	// identity, not embedded data: the embedded file carries every
	// collation's Config and LoadCollation fills this in.
	Collation Collation `json:"-"`
	PackSize  int       `json:"pack_size"`
	Source    string    `json:"source"`
	Config    Config    `json:"config"`
}

// Load returns the embedded, validated booster spec for the set code
// ("FDN", "BLB", ...) at the default collation.
func Load(code string) (Spec, error) {
	return LoadCollation(code, DefaultCollation)
}

// LoadCollation returns the embedded, validated booster spec for the set
// code at the named collation. An unknown set or collation is an error
// naming what the file does carry.
func LoadCollation(code string, c Collation) (Spec, error) {
	if code == "" || strings.ContainsAny(code, "/\\.") {
		return Spec{}, fmt.Errorf("setdata: bad set code %q", code)
	}
	if c == "" {
		return Spec{}, fmt.Errorf("setdata: %s: empty collation", code)
	}
	b, err := sets.ReadFile("sets/" + code + ".json")
	if err != nil {
		return Spec{}, fmt.Errorf("setdata: unknown set %q", code)
	}
	f, err := parseSetFile(b)
	if err != nil {
		return Spec{}, fmt.Errorf("setdata: %s: %w", code, err)
	}
	if f.Set != code {
		return Spec{}, fmt.Errorf("setdata: sets/%s.json carries set %q", code, f.Set)
	}
	cfg, ok := f.Configs[string(c)]
	if !ok {
		return Spec{}, fmt.Errorf("setdata: %s: no %q collation (carries %s)", code, c, quoteJoin(collationNames(f.Configs)))
	}
	spec, err := specFor(f, c, cfg)
	if err != nil {
		return Spec{}, fmt.Errorf("setdata: %s %s: %w", code, c, err)
	}
	return spec, nil
}

// specFor builds and validates the Spec one embedded file's config yields,
// deriving the pack size the variants share.
func specFor(f setFile, c Collation, cfg Config) (Spec, error) {
	ps, err := packSize(cfg)
	if err != nil {
		return Spec{}, err
	}
	spec := Spec{
		Code:      f.Set,
		Collation: c,
		Name:      f.Name,
		PackSize:  ps,
		Source:    f.Source,
		Config:    cfg,
	}
	if err := spec.Validate(); err != nil {
		return Spec{}, err
	}
	return spec, nil
}

// packSize returns the pack size the config's variants produce: the
// contents sum of the first variant, which every variant must match.
func packSize(cfg Config) (int, error) {
	if len(cfg.Variants) == 0 {
		return 0, fmt.Errorf("config has no variants")
	}
	ps := sumContents(cfg.Variants[0])
	for i, v := range cfg.Variants[1:] {
		if got := sumContents(v); got != ps {
			return 0, fmt.Errorf("variant %d's contents sum to %d, want the other variants' %d", i+1, got, ps)
		}
	}
	return ps, nil
}

// sumContents sums a variant's sheet counts.
func sumContents(v Variant) int {
	total := 0
	for _, n := range v.Contents {
		total += n
	}
	return total
}

// Codes returns the set codes with an embedded spec, sorted.
func Codes() []string {
	entries, err := sets.ReadDir("sets")
	if err != nil {
		return nil
	}
	var codes []string
	for _, e := range entries {
		name := e.Name()
		if !strings.HasSuffix(name, ".json") {
			continue
		}
		codes = append(codes, strings.TrimSuffix(name, ".json"))
	}
	sort.Strings(codes)
	return codes
}

// Collations returns the collations the set's embedded file carries,
// sorted. An unknown set (or an unreadable one) yields nil.
func Collations(code string) []Collation {
	if code == "" || strings.ContainsAny(code, "/\\.") {
		return nil
	}
	b, err := sets.ReadFile("sets/" + code + ".json")
	if err != nil {
		return nil
	}
	f, err := parseSetFile(b)
	if err != nil {
		return nil
	}
	names := collationNames(f.Configs)
	out := make([]Collation, len(names))
	for i, n := range names {
		out[i] = Collation(n)
	}
	return out
}

// collationNames lists a set file's collation keys, sorted.
func collationNames(configs map[string]Config) []string {
	names := make([]string, 0, len(configs))
	for name := range configs {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// quoteJoin spells names as a comma-separated quoted list.
func quoteJoin(names []string) string {
	quoted := make([]string, len(names))
	for i, n := range names {
		quoted[i] = fmt.Sprintf("%q", n)
	}
	return strings.Join(quoted, ", ")
}

// Validate checks a spec's internal consistency: the set facts are present,
// the variants' weights cover the config's total weight, every variant's
// contents exist and sum to PackSize, and every sheet's cards carry the
// MTGJSON facts with weights that sum to the sheet's total weight.
func (s *Spec) Validate() error {
	if s.Code == "" || s.Name == "" {
		return fmt.Errorf("spec needs a code and a name")
	}
	if s.PackSize <= 0 {
		return fmt.Errorf("pack_size must be positive")
	}
	cfg := s.Config
	if len(cfg.Variants) == 0 {
		return fmt.Errorf("config has no variants")
	}
	if cfg.TotalWeight <= 0 {
		return fmt.Errorf("config total_weight must be positive")
	}
	weight := 0
	for i, v := range cfg.Variants {
		if v.Weight <= 0 {
			return fmt.Errorf("variant %d weight must be positive", i)
		}
		weight += v.Weight
		if len(v.Contents) == 0 {
			return fmt.Errorf("variant %d draws from no sheet", i)
		}
		total := 0
		for sheet, count := range v.Contents {
			if count <= 0 {
				return fmt.Errorf("variant %d sheet %q count must be positive", i, sheet)
			}
			if _, ok := cfg.Sheets[sheet]; !ok {
				return fmt.Errorf("variant %d names missing sheet %q", i, sheet)
			}
			total += count
		}
		if total != s.PackSize {
			return fmt.Errorf("variant %d contents sum to %d, want pack_size %d", i, total, s.PackSize)
		}
	}
	if weight != cfg.TotalWeight {
		return fmt.Errorf("variant weights sum to %d, want total_weight %d", weight, cfg.TotalWeight)
	}
	if len(cfg.Sheets) == 0 {
		return fmt.Errorf("config has no sheets")
	}
	for name, sheet := range cfg.Sheets {
		if len(sheet.Cards) == 0 {
			return fmt.Errorf("sheet %q is empty", name)
		}
		total := 0
		for _, c := range sheet.Cards {
			if c.Name == "" || c.Number == "" {
				return fmt.Errorf("sheet %q has a card without a name or collector number", name)
			}
			if c.Weight <= 0 {
				return fmt.Errorf("sheet %q card %q has weight %d, want positive", name, c.Name, c.Weight)
			}
			if !validRarity(c.Rarity) {
				return fmt.Errorf("sheet %q card %q carries invalid rarity %q", name, c.Name, c.Rarity)
			}
			total += c.Weight
		}
		if total != sheet.TotalWeight {
			return fmt.Errorf("sheet %q card weights sum to %d, want total_weight %d", name, total, sheet.TotalWeight)
		}
	}
	return nil
}

// validRarity reports whether r is one of the six rarity letters.
func validRarity(r limited.Rarity) bool {
	switch r {
	case limited.Common, limited.Uncommon, limited.Rare, limited.Mythic, limited.Land, limited.Special:
		return true
	}
	return false
}

// setFile is the embedded sets/<SET>.json shape: the trimmed MTGJSON set
// file, all its collations and the MIT licence notice.
type setFile struct {
	Set     string            `json:"set"`
	Name    string            `json:"name"`
	Source  string            `json:"source"`
	License string            `json:"license"`
	Configs map[string]Config `json:"configs"`
}

// parseSetFile decodes an embedded set file, refusing fields the setFile
// types do not declare, so a generator/spec drift fails at Load instead of
// silently dropping data.
func parseSetFile(b []byte) (setFile, error) {
	var f setFile
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&f); err != nil {
		return setFile{}, err
	}
	return f, nil
}

// Compile validates a raw trimmed MTGJSON set file (the
// draft/limited/setdata/mtgjson/<SET>.json shape) and returns the canonical
// embedded form: the same records with the rarity words mapped to
// limited.Rarity letters, re-encoded indented with sorted keys. It fails on
// any config that would not load as a Spec. internal/gen writes what this
// returns to sets/<SET>.json.
func Compile(raw []byte) ([]byte, error) {
	f, err := compileSetFile(raw)
	if err != nil {
		return nil, fmt.Errorf("setdata: compile: %w", err)
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	if err := enc.Encode(f); err != nil {
		return nil, fmt.Errorf("setdata: compile: %w", err)
	}
	return buf.Bytes(), nil
}

// compileSetFile parses a raw MTGJSON set file, converts it to the embedded
// shape and proves every collation loads as a Spec.
func compileSetFile(raw []byte) (setFile, error) {
	var rf rawSetFile
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&rf); err != nil {
		return setFile{}, err
	}
	if rf.Set == "" || rf.Name == "" {
		return setFile{}, fmt.Errorf("%s: raw file carries no set code or name", rf.Set)
	}
	f := setFile{Set: rf.Set, Name: rf.Name, Source: rf.Source, License: rf.License, Configs: map[string]Config{}}
	for name, rc := range rf.Configs {
		cfg, err := compileConfig(rc)
		if err != nil {
			return setFile{}, fmt.Errorf("%s collation %q: %w", rf.Set, name, err)
		}
		f.Configs[name] = cfg
	}
	for _, name := range collationNames(f.Configs) {
		spec, err := specFor(f, Collation(name), f.Configs[name])
		if err != nil {
			return setFile{}, fmt.Errorf("%s collation %q: %w", f.Set, name, err)
		}
		if spec.PackSize <= 0 {
			return setFile{}, fmt.Errorf("%s collation %q: pack size %d", f.Set, name, spec.PackSize)
		}
	}
	return f, nil
}

// compileConfig converts one raw collation config, mapping the cards'
// rarity words to letters.
func compileConfig(rc rawConfig) (Config, error) {
	cfg := Config{
		SourceSetCodes: rc.SourceSetCodes,
		TotalWeight:    rc.TotalWeight,
		Variants:       make([]Variant, len(rc.Variants)),
		Sheets:         map[string]Sheet{},
	}
	for i, rv := range rc.Variants {
		if len(rv.Contents) == 0 {
			return Config{}, fmt.Errorf("variant %d draws from no sheet", i)
		}
		cfg.Variants[i] = Variant{Weight: rv.Weight, Contents: rv.Contents}
	}
	for name, rs := range rc.Sheets {
		sheet, err := compileSheet(rs)
		if err != nil {
			return Config{}, fmt.Errorf("sheet %q: %w", name, err)
		}
		cfg.Sheets[name] = sheet
	}
	return cfg, nil
}

// compileSheet converts one raw sheet, mapping its cards' rarity words to
// letters.
func compileSheet(rs rawSheet) (Sheet, error) {
	sheet := Sheet{
		TotalWeight:     rs.TotalWeight,
		Foil:            rs.Foil,
		BalanceColors:   rs.BalanceColors,
		AllowDuplicates: rs.AllowDuplicates,
		Fixed:           rs.Fixed,
		Cards:           make([]SheetCard, len(rs.Cards)),
	}
	for i, rc := range rs.Cards {
		r, ok := rarityWords[rc.Rarity]
		if !ok {
			return Sheet{}, fmt.Errorf("card %q carries unknown rarity %q", rc.Name, rc.Rarity)
		}
		sheet.Cards[i] = SheetCard{
			UUID:   rc.UUID,
			Name:   rc.Name,
			Set:    rc.Set,
			Number: rc.Number,
			Rarity: r,
			Colors: rc.Colors,
			Weight: rc.Weight,
		}
	}
	return sheet, nil
}

// rarityWords maps the MTGJSON rarity words to the limited.Rarity letters.
var rarityWords = map[string]limited.Rarity{
	"common":   limited.Common,
	"uncommon": limited.Uncommon,
	"rare":     limited.Rare,
	"mythic":   limited.Mythic,
	"land":     limited.Land,
	"special":  limited.Special,
}

// rawSetFile and friends mirror the raw trimmed MTGJSON file's shape (the
// same keys as setFile, but the card rarity as the word MTGJSON spells).
type rawSetFile struct {
	Set     string               `json:"set"`
	Name    string               `json:"name"`
	Source  string               `json:"source"`
	License string               `json:"license"`
	Configs map[string]rawConfig `json:"configs"`
}

type rawConfig struct {
	SourceSetCodes []string            `json:"source_set_codes"`
	TotalWeight    int                 `json:"total_weight"`
	Variants       []rawVariant        `json:"variants"`
	Sheets         map[string]rawSheet `json:"sheets"`
}

type rawVariant struct {
	Weight   int            `json:"weight"`
	Contents map[string]int `json:"contents"`
}

type rawSheet struct {
	TotalWeight     int       `json:"total_weight"`
	Foil            bool      `json:"foil"`
	BalanceColors   bool      `json:"balance_colors"`
	AllowDuplicates bool      `json:"allow_duplicates"`
	Fixed           bool      `json:"fixed"`
	Cards           []rawCard `json:"cards"`
}

type rawCard struct {
	UUID   string `json:"uuid"`
	Name   string `json:"name"`
	Set    string `json:"set"`
	Number string `json:"number"`
	Rarity string `json:"rarity"`
	Colors string `json:"colors"`
	Weight int    `json:"weight"`
}
